"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$paths = @(
  '"'../.codex/design_charter.md',
  '.change-loop/fresh-suite/H05-marker-unlink/plan.md',
  '.change-loop/fresh-suite/H05-marker-unlink/plan-review.md',
  '.change-loop/fresh-suite/H05-marker-unlink/plan-amendments.md',
  '.change-loop/fresh-suite/H05-marker-unlink/state/test_report.md',
  '.change-loop/fresh-suite/H05-marker-unlink/DESIGN_CHARTER_CHECKS.md'
)
foreach ("'$path in $paths) {
  if (Test-Path -LiteralPath $path) {
    Write-Output "--- $path ---"
    Get-Content -LiteralPath $path -Raw
  } else {
    Write-Output "--- MISSING: $path ---"
  }
}
Write-Output '"'--- STATUS ---'
git status --short
Write-Output '--- FILES ---'
rg --files -g '"'!*node_modules*'"' | Select-Object -First 250"

